referenceSolutionTemplate:
#include <stdio.h>

#define SLOTS 10

int shelf[SLOTS];
int used[SLOTS];

/* 编号算门牌号：编号除以 10 的余数 */
int slot_of(int id) {
    return id % SLOTS;
}

/* 存一只：从算出来的格子开始，有人住了就往后挪一格，还撞就再挪；住下时记一笔 */
void put(int id) {
    int slot = slot_of(id);
    while (used[slot]) {
        slot = (slot + 1) % SLOTS;
    }
    shelf[slot] = id;
    used[slot] = 1;
}

/* 找一只：从算出来的格子开始往后敲，答「敲了几次才找到」；敲到空格子就答 0 */
int find(int id) {
    int slot = slot_of(id);
    int tries = 0;
    while (used[slot]) {
        tries++;
        if (shelf[slot] == id) {
            return tries;
        }
        slot = (slot + 1) % SLOTS;
    }
    return 0;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) {
        return 1;
    }
    int a[64];
    for (int i = 0; i < n; i++) {
        if (scanf("%d", &a[i]) != 1) {
            return 1;
        }
    }

    for (int i = 0; i < n; i++) {
        put(a[i]);
    }

    int last = a[n - 1];
    int times = find(last);
    if (times > 0) {
        printf("最后递进来的 %d：比了 %d 次\n", last, times);
    } else {
        printf("最后递进来的 %d：没找到\n", last);
    }

    if (find(0) > 0) {
        printf("编号 0：找着了\n");
    } else {
        printf("编号 0：没找到\n");
    }
    return 0;
}
